import{_ as l,a0 as i,w as p,s as u,ao as n,I as s,x as t,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"Meta 開源了語言翻譯 AI 模型 | LCTT x X-CMD","titleTemplate":false,"description":"Meta 開源了語言翻譯 AI 模型 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Meta 開源了語言翻譯 AI 模型 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Meta 開源了語言翻譯 AI 模型 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220708 Meta-s AI Model That Helps Overcome Language Barrier Is Now Open-Source","title":"Meta 開源了語言翻譯 AI 模型","tag":"202207","desc":""},"relativePath":"202207/20220708 Meta-s AI Model That Helps Overcome Language Barrier Is Now Open-Source.md","filePath":"[post].md"}'),m={name:"202207/20220708 Meta-s AI Model That Helps Overcome Language Barrier Is Now Open-Source.md"};function d(f,e,g,b,T,L){const a=i("Link");return p(),u("div",null,[e[20]||(e[20]=n('<h1 id="meta-開源了語言翻譯-ai-模型" tabindex="-1">Meta 開源了語言翻譯 AI 模型 <a class="header-anchor" href="#meta-開源了語言翻譯-ai-模型" aria-label="Permalink to “Meta 開源了語言翻譯 AI 模型”">​</a></h1><blockquote><p>Meta 的 “<ruby>不落下任何語言<rt>No Language Left Behind</rt></ruby>” 是一個宏大的開源項目，旨在以最高準確度翻譯語言。</p></blockquote><p><img src="https://news.itsfoss.com/wp-content/uploads/2022/07/meta-makes-ai-language-model-opensource.jpg" alt="meta"></p><p>Meta（前身是 Facebook）在開源世界做出了不小的貢獻。Meta 除了專注於<ruby>元宇宙<rt>Metaverse</rt></ruby>和其社交媒體平台外，還致力於各種研究和創新工作，比如 React（一個 JaveScript 庫）。</p><p>現在，Meta 的研究人員決定開源一個叫 “<ruby>不落下任何語言<rt>No Language Left Behind</rt></ruby>” 項目。</p><p>（LCTT 校注：這個直譯項目名稱不夠好聽，我來拋磚引玉，似可稱做“無人獨語”，讀者有什麼建議嗎？）</p><h3 id="meta-試圖不落下任何語言" tabindex="-1">Meta 試圖不落下任何語言 <a class="header-anchor" href="#meta-試圖不落下任何語言" aria-label="Permalink to “Meta 試圖不落下任何語言”">​</a></h3><p><img src="https://youtu.be/uCxSPPiwrNE" alt="200 languages within a single AI model: A breakthrough in high-quality machine translation"></p><p>目前，雖然世界上有大約 7000 個在使用中的語言，但大多數在線的內容都是以少數的流行語言來提供的，比如英語。這讓許多不懂這些語言的人處於不利的地位。</p><p>雖然現存的許多翻譯工具，但語法錯誤會讓錯誤變得難以閲讀和理解。另外，如果你想把內容翻譯為一個不流行的語言（特別是非洲和亞洲的一些語言），翻譯體驗不會很好。</p><p>因此，Meta 正在開發有最高質量的翻譯工具，可以幫助解決這一全球性的問題。</p><p>NLLB-200（<ruby>不落下任何語言<rt>No Language Left Behind</rt></ruby>） 是一個人工智能翻譯模型，其可以翻譯 200 多種語言。該模型在每種語言中的翻譯結果是通過一個名為 FLORES-200 複雜數據集來確定和評估的。</p><p>正如 Meta 所説，NLLB 的翻譯結果比以前的人工智能研究方法好 40% 。對於一些最不常見的語言，其翻譯準確率甚至超過 70%。了不起的工作！</p><p>為了幫助開發項目和提高模型的翻譯質量，Meta 向所有感興趣的研究人員開放了源代碼，包括 NLLB-200 模型、FLORES-200 資料庫、模型訓練和重建訓練資料庫的代碼。</p>',14)),s("p",null,[e[2]||(e[2]=t("你可以在 ",-1)),r(a,{href:"https://github.com/facebookresearch/fairseq/tree/nllb"},{default:o(()=>[...e[0]||(e[0]=[t("GitHub",-1)])]),_:1}),e[3]||(e[3]=t(" 上找到源代碼，並且可以在該項目的 ",-1)),r(a,{href:"https://ai.facebook.com/blog/nllb-200-high-quality-machine-translation/"},{default:o(()=>[...e[1]||(e[1]=[t("Blog",-1)])]),_:1}),e[4]||(e[4]=t(" 上了解它的更多信息。",-1))]),e[21]||(e[21]=n('<h3 id="對社會事業的鼓勵" tabindex="-1">對社會事業的鼓勵 <a class="header-anchor" href="#對社會事業的鼓勵" aria-label="Permalink to “對社會事業的鼓勵”">​</a></h3><p>Meta 宣佈向從事<ruby>聯合國可持續發展目標<rt>UN Sustainable Development Goals</rt></ruby>任何領域工作和翻譯非洲語言的非營利組織和研究人員提供高達 20 萬美元的捐贈，也鼓勵其他學術領域如語言學和機器翻譯的研究人員申請。</p><h3 id="項目的影響" tabindex="-1">項目的影響 <a class="header-anchor" href="#項目的影響" aria-label="Permalink to “項目的影響”">​</a></h3><p>儘管 Meta 主要打算在其數字平台上，特別是在“元宇宙”上使用 NLLB，但 NLLB 也有可能在其他領域產生巨大影響。</p><p>許多用户可以用他們的母語輕鬆地訪問和閲讀在線資源。項目開源後，社區應該能夠幫助實現這個目標。</p><p><em>你對 Meta 的這個項目有什麼看法？</em></p><hr>',7)),s("p",null,[e[6]||(e[6]=t("via: ",-1)),r(a,{href:"https://news.itsfoss.com/meta-open-source-ai-model/"},{default:o(()=>[...e[5]||(e[5]=[t("https://news.itsfoss.com/meta-open-source-ai-model/",-1)])]),_:1})]),s("p",null,[e[11]||(e[11]=t("作者：",-1)),r(a,{href:"https://news.itsfoss.com/author/rishabh/"},{default:o(()=>[...e[7]||(e[7]=[t("Rishabh Moharir",-1)])]),_:1}),e[12]||(e[12]=t(" 選題：",-1)),r(a,{href:"https://github.com/lkxed"},{default:o(()=>[...e[8]||(e[8]=[t("lkxed",-1)])]),_:1}),e[13]||(e[13]=t(" 譯者：",-1)),r(a,{href:"https://github.com/fenglyulin"},{default:o(()=>[...e[9]||(e[9]=[t("fenglyulin",-1)])]),_:1}),e[14]||(e[14]=t(" 校對：",-1)),r(a,{href:"https://github.com/wxy"},{default:o(()=>[...e[10]||(e[10]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[17]||(e[17]=t("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[15]||(e[15]=[t("LCTT",-1)])]),_:1}),e[18]||(e[18]=t(" 原創編譯，",-1)),r(a,{href:"https://linux.cn/"},{default:o(()=>[...e[16]||(e[16]=[t("Linux中國",-1)])]),_:1}),e[19]||(e[19]=t(" 榮譽推出",-1))])])}const N=l(m,[["render",d]]);export{I as __pageData,N as default};
